package cl.skinspad.reporte.soporte;
import java.time.*;import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import static cl.skinspad.reporte.soporte.EstadosSoporte.*;import static cl.skinspad.reporte.soporte.SoporteDtos.*;import static cl.skinspad.reporte.soporte.SoporteIdentidad.*;
@Service @RequiredArgsConstructor public class ReporteService {
 private final ReporteRepository reportes;private final SoporteCuotas cuotas;private final SoporteArchivos archivos;private final SoporteRegistro registro;private final SoporteContexto contexto;private final ObjetivoInicializador inicializador;private final SoporteObjetivoRepository objetivos;
 @org.springframework.beans.factory.annotation.Value("${soporte.umbral-reportes:3}") private int umbral;
 public void preparar(NuevoReporte r,Actor a){cliente(a);var d=contexto.objetivo(r.tipoObjetivo(),r.objetivoId(),a);var k=r.tipoObjetivo()+":"+d.id();try{inicializador.crear(k);}catch(org.springframework.dao.DataIntegrityViolationException e){if(!objetivos.existsById(k))throw e;}}
 public Reporte acceso(Long id,Actor a){var r=reportes.findById(id).orElseThrow(()->new jakarta.persistence.EntityNotFoundException("Reporte no encontrado"));propietario(r.getReportanteId(),a);return r;}
 public ReporteVista vista(Reporte r,Actor a){return new ReporteVista(r.getId(),r.getVersion(),r.getTipoObjetivo(),r.getObjetivoId(),r.getMotivo(),r.getDescripcion(),a.admin()?r.getEstado().name():simple(r.getEstado()),a.admin()?r.getPrioridad():null,a.admin()?r.getAdminAsignadoId():null,r.getFechaCreacion(),!r.isAccionPendiente()?r.getResolucion():null,a.admin()?r.getAccionTomada():null,a.admin()&&r.isAccionPendiente(),a.admin()?r.getErrorAccion():null,r.getEvidenciaUrls()==null||r.getEvidenciaUrls().isBlank()?List.of():Arrays.asList(r.getEvidenciaUrls().split("\n")),archivos.listar("REPORTE",r.getId()));}
 public ReporteVista obtener(Long id,Actor a){return vista(acceso(id,a),a);}
 public List<ReporteVista> mios(Actor a){return reportes.findByReportanteIdOrderByFechaCreacionDesc(a.id()).stream().map(r->vista(r,a)).toList();}
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED) public ReporteVista crear(NuevoReporte r,Actor a){cliente(a);var d=contexto.objetivo(r.tipoObjetivo(),r.objetivoId(),a);objetivos.bloquear(r.tipoObjetivo()+":"+d.id()).orElseThrow();String clave=a.id()+":"+r.tipoObjetivo()+":"+d.id();if(reportes.existsByClaveAbierta(clave))throw new IllegalStateException("Ya tienes un reporte abierto sobre este objetivo");if(r.motivo()==null)throw new IllegalArgumentException("Motivo obligatorio");cuotas.consumir(a.id());
  var n=new Reporte();n.setReportanteId(a.id());n.setTipoObjetivo(r.tipoObjetivo());n.setObjetivoId(d.id());n.setDenunciadoId(d.denunciado());n.setClaveAbierta(clave);n.setMotivo(r.motivo());n.setDescripcion(ValidacionSoporte.texto(r.descripcion(),4000));n.setEvidenciaUrls(String.join("\n",ValidacionSoporte.urls(r.evidenciaUrls())));if(d.enCurso())n.setPrioridad(Prioridad.ALTA);reportes.saveAndFlush(n);archivos.guardar("REPORTE",n.getId(),null,r.adjuntos());registro.evento("REPORTE",n.getId(),a.id(),"CREAR",null,n.getEstado(),"Reporte creado, sin sanción automática");
  if(r.tipoObjetivo()==Objetivo.PUBLICACION){var abiertos=reportes.findByTipoObjetivoAndObjetivoId(r.tipoObjetivo(),d.id()).stream().filter(x->abierto(x.getEstado())).toList();if(abiertos.stream().map(Reporte::getReportanteId).distinct().count()>=Math.max(2,umbral)){for(var x:abiertos)if(x.getPrioridad()!=Prioridad.URGENTE){registro.evento("REPORTE",x.getId(),"SISTEMA","PRIORIDAD",x.getPrioridad(),Prioridad.URGENTE,"Umbral de reportantes distintos");x.setPrioridad(Prioridad.URGENTE);}}}
  registro.avisar("R-"+n.getId()+"-CREAR","ADMIN",n.getPrioridad()==Prioridad.URGENTE?"Publicación con varios reportes · revisión urgente":d.enCurso()?"Reporte de operación activa · prioridad alta":"Nuevo reporte para revisar","/admin/soporte/reportes/"+n.getId());reportes.flush();return vista(n,a);
 }
 @Transactional public ReporteVista asignar(Long id,Asignacion p,Actor a){var r=reportes.bloquear(id).orElseThrow();if(!a.admin())throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN);ValidacionSoporte.version(p.version(),r.getVersion());if(r.isAccionPendiente()||!abierto(r.getEstado()))throw new IllegalStateException("El reporte no está disponible para asignación");contexto.adminAsignable(p.adminId());String m=ValidacionSoporte.texto(p.motivo(),1000);if(!Objects.equals(r.getAdminAsignadoId(),p.adminId())){registro.evento("REPORTE",id,a.id(),"ASIGNAR",r.getAdminAsignadoId(),p.adminId(),m);r.setAdminAsignadoId(p.adminId());}reportes.flush();return vista(r,a);}
 @Transactional public String solicitar(Long id,Resolver p,Actor a){if(!a.admin())throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN);var r=reportes.bloquear(id).orElseThrow(()->new jakarta.persistence.EntityNotFoundException("Reporte no encontrado"));ValidacionSoporte.version(p.version(),r.getVersion());if(r.isAccionPendiente()||!abierto(r.getEstado()))throw new IllegalStateException("Reporte finalizado o con una acción en proceso");if(!Boolean.TRUE.equals(p.confirmado())||p.accion()==null)throw new IllegalArgumentException("Confirma explícitamente la acción");if(p.estado()!=Estado.RESUELTO&&p.estado()!=Estado.RECHAZADO&&p.estado()!=Estado.EN_REVISION)throw new IllegalArgumentException("Estado de resolución inválido");if(p.estado()==Estado.RECHAZADO&&p.accion()!=Accion.SIN_ACCION)throw new IllegalArgumentException("Rechazar una denuncia no ejecuta sanciones");if((p.accion()==Accion.PUBLICACION_DESPUBLICADA&&r.getTipoObjetivo()!=Objetivo.PUBLICACION)||((p.accion()==Accion.OPERACION_CONGELADA||p.accion()==Accion.OPERACION_REEMBOLSADA)&&r.getTipoObjetivo()!=Objetivo.OPERACION))throw new IllegalArgumentException("La acción no corresponde al objetivo");
  if(r.getEstado()!=p.estado())transicion(r.getEstado(),p.estado(),false,true);
  contexto.validarAccion(r,p.accion());
  String m=ValidacionSoporte.texto(p.motivo(),400),resumen=ValidacionSoporte.texto(p.resumenPublico(),1000);String ref="REP-"+id+"-"+UUID.randomUUID();r.setReferenciaAccion(ref);r.setEstadoSolicitado(p.estado());r.setAdminResolutorId(a.id());r.setMotivoInterno(m);r.setResolucion(resumen);r.setAccionTomada(p.accion());r.setAccionPendiente(true);r.setErrorAccion(null);registro.evento("REPORTE",id,a.id(),"SOLICITAR_ACCION",r.getEstado(),p.accion(),ref+" · "+m);return ref;
 }
 @Transactional public void finalizar(Long id,String ref){var r=reportes.bloquear(id).orElseThrow();if(!r.isAccionPendiente()||!ref.equals(r.getReferenciaAccion()))return;var estado=r.getEstadoSolicitado();registro.evento("REPORTE",id,r.getAdminResolutorId(),"ACCION_CONFIRMADA",r.getEstado(),estado,ref+" · "+r.getAccionTomada()+" · "+r.getMotivoInterno());r.setEstado(estado);r.setAccionPendiente(false);r.setErrorAccion(null);if(!abierto(estado)){r.setFechaResolucion(Instant.now());r.setClaveAbierta(null);}registro.avisar(ref+"-RESULTADO",r.getReportanteId(),abierto(estado)?"Tu reporte está en revisión":"Tu reporte tiene una resolución","/cliente/soporte/reportes/"+id);if(r.getAccionTomada()==Accion.ADVERTENCIA)registro.avisar(ref+"-AVISO",r.getDenunciadoId(),"Advertencia de administración: revisa tus publicaciones y cumple las normas del marketplace","/cliente/soporte");}
 @Transactional public void fallo(Long id,String ref,String mensaje){var r=reportes.bloquear(id).orElseThrow();if(r.isAccionPendiente()&&ref.equals(r.getReferenciaAccion())){r.setErrorAccion(mensaje);registro.avisar(ref+"-FALLO","ADMIN","Acción de moderación pendiente de conciliación","/admin/soporte/reportes/"+id);}}

 @Transactional public void noEjecutada(Long id,String ref){var r=reportes.bloquear(id).orElseThrow();if(r.isAccionPendiente()&&ref.equals(r.getReferenciaAccion())){registro.evento("REPORTE",id,r.getAdminResolutorId(),"ACCION_RECHAZADA",r.getEstado(),r.getEstado(),ref+" · El servicio rechazó la acción antes de ejecutarla");r.setAccionPendiente(false);r.setResolucion(null);r.setErrorAccion("El objetivo rechazó la acción; recarga y elige una acción permitida");}}
}
